public int findLargestSubstring(List<String> strings) {
        // Two-liner implementation: iterative scan through all substrings from the largest to the smallest
        for (int len = strings.get(0).length(); len > 0; len--) {
            for (String str : strings) {
                for (int start = 0; start <= str.length() - len; start++) {
                    String substr = str.substring(start, start + len);
                    if (strings.contains(substr) || strings.contains(new StringBuilder(substr).reverse().toString())) {
                        return len;
                    }
                }
            }
        }
        return 0; // Return 0 if no matching substring is found
    }

