public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || n > 512) {
        throw new IllegalArgumentException("Size n should be within 1 to 512");
    }

    int sx = start[0];
    int sy = start[1];
    int ex = end[0];
    int ey = end[1];

    if (sx < 0 || sy < 0 || sx >= n || sy >= n || ex < 0 || ey < 0 || ex >= n || ey >= n) {
        throw new IllegalArgumentException("Start and end coordinates should be within the space of size n");
    }

    HashSet<String> visited = new HashSet<>();
    Queue<int[]> queue = new LinkedList<>();

    visited.add(sx + "," + sy);
    queue.add(new int[]{sx, sy});

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int cx = current[0];
        int cy = current[1];

        if (cx == ex && cy == ey) {
            return "can be travelled";
        }

        for (int[] direction : paths) {
            int nx = cx + direction[0];
            int ny = cy + direction[1];

            if (nx >= 0 && nx < n && ny >= 0 && ny < n &&
                !visited.contains(nx + "," + ny) &&
                paths[x][y] == paths[nx][ny]) {

                visited.add(nx + "," + ny);
                queue.add(new int[]{nx, ny});
            }
        }
    }

    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    // Validate input
    if (word1 == null || word2 == null || word1.isEmpty() || word2.isEmpty()) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Count common letters
    int commonLetters = 0;
    for (char c : word1.toCharArray()) {
        if (word2.indexOf(c) >= 0) {
            commonLetters++;
        }
    }

    // Calculate the approximate value
    BigInteger gcd = BigInteger.valueOf(commonLetters).gcd(BigInteger.valueOf(word1.length() + word2.length()));
    commonLetters /= gcd.intValue();
    BigInteger denominators = BigInteger.valueOf(word1.length() + word2.length()).divide(gcd);

    return "appx(" + word1 + ", " + word2 + ") = " + commonLetters + "/" + denominators.toString();
}

