public int minTime(int n, int[][] edges, boolean[] hasApple) {
        List<TreeNode> nodes = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            nodes.add(new TreeNode(i));
        }
        for (int[] edge : edges) {
            TreeNode parent = nodes.get(edge[0]);
            TreeNode child = nodes.get(edge[1]);
            parent.children.add(child);
            child.children.add(parent);
        }

        int ans = dfs(nodes.get(0), hasApple);
        return ans == 0 ? 0 : ans - 2; // Min time + 2 for the return to the starting point
    }

private int dfs(TreeNode node, boolean[] hasApple) {
        int res = 0;
        for (TreeNode child : node.children) {
            int childResult = dfs(child, hasApple);
            if (childResult > 0) { // A child has an apple
                res += childResult + 2; // child time + 2 for the return to the starting point
            } else if (hasApple[child.val]) { // Child node itself has an apple
                res += childResult + 2; // child time + 2 for the return to the starting point
            }
        }
        return res;
    }

public String sortString(String s) {
        int[] charCount = new int[26];
        Arrays.fill(charCount, 0);

        // Count occurrences of each character
        for (char c : s.toCharArray()) {
            charCount[c - 'a']++;
        }

        StringBuilder result = new StringBuilder();
        int i = 0;

        // Sort characters Alphabatically
        while (true) {
            for (int j = 0; j < 26; j++) {
                if (charCount[j] > 0) {
                    result.append((char) (j + 'a'));
                    charCount[j]--;
                }
            }
            // Reverse to sort in descending order
            char[] reversed = result.reverse().toString().toCharArray();
            result = new StringBuilder();
            for (char c : reversed) {
                result.append(c);
            }
        }

        return result.toString();
    }

public boolean splitArraySameAverage(int[] nums) {
    if (nums.length <= 2) return false;

    int total = 0;
    for (int num : nums) total += num;

    if (total * 2 % nums.length != 0) return false;

    int target = total * 2 / nums.length;

    int start = 1;
    int end = nums.length - 2;
    int currentSum = nums[0] + nums[end];

    while (start < end) {
        if (currentSum == target) {
            int presum = 0;
            for (int i = 0; i < nums.length - 2; i++) {
                presum += nums[i];
                if (presum == target) return true;
            }
        }

        if (currentSum < target) {
            currentSum += nums[start];
            start++;
        } else {
            currentSum -= nums[end];
            end--;
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int[] dp = new int[cost.length + 1];

    // Base cases: the cost to reach the top from the first or second step is the value of that step
    dp[0] = cost[0];
    dp[1] = cost[1];

    // Fill the dp array
    for (int i = 2; i <= cost.length; i++) {
        // The minimum cost to reach i is the minimum of the cost to reach i-1 or i-2, plus the cost of i
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i - 1];
    }

    // The minimum cost to reach the top is the minimum of the cost to reach the second last or last step
    return Math.min(dp[cost.length - 1], dp[cost.length]);
}

