public int minInsertions(String s) {
    // Create a stack to store characters for balance
    Stack<Character> stack = new Stack<>();
    int count = 0;

    for (char c : s.toCharArray()) {
        // If character is '('
        if (c == '(') {
            // Push '(' onto the stack
            stack.push(c);
        } else { // If character is ')'
            // If stack is empty, we need to insert '(', so increment count and push ')'
            if (stack.isEmpty()) {
                count++;
                stack.push(')');
            } else {// If stack is not empty, we pop the top element and see if it matches ')'
                stack.pop();
            }
        }
    }

    // The number of '(' in the stack is the number of unmatched right brackets
    int unmatchedLefts = stack.size();

    // Total insertions required is the sum of unmatched '(' and unmatched ')' and additional ')'
    return unmatchedLefts + unmatchedLefts + s.length() - unmatchedLefts * 2;
}

