public int maxAbsoluteSum(int[] nums) {
    int maxSoFar = 0, minSoFar = 0;
    int maxExpSum = Integer.MIN_VALUE, minExpSum = Integer.MAX_VALUE;

    for (int num : nums) {
        maxSoFar = Math.max(num, maxSoFar + num);
        minSoFar = Math.min(num, minSoFar + num);

        maxExpSum = Math.max(maxExpSum, maxSoFar);
        minExpSum = Math.min(minExpSum, minSoFar);
    }

    // In case all elements are negative, the max is the minimum of all elements
    // If all elements are positive, the max is the maximum of all elements
    return Math.max(Math.abs(maxExpSum), Math.abs(minExpSum));
}

public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci sequence up to a certain threshold
    int threshold = (int) (Math.log(Double.POSITIVE_INFINITY) / Math.log(5.0));
    List<Integer> fibonacci = generateFibonacci(threshold);

    // Find the minimum number of Fibonacci numbers that sum to k
    int count = 0;
    for (int num : fibonacci) {
        while (k >= num) {
            k -= num;
            count++;
        }
    }

    return count;
}

private List<Integer> generateFibonacci(int threshold) {
    List<Integer> fibonacci = new ArrayList<>();
    fibonacci.add(1);
    fibonacci.add(1);

    while (true) {
        int next = fibonacci.get(fibonacci.size() - 1) + fibonacci.get(fibonacci.size() - 2);
        if (next > threshold) {
            break;
        }
        fibonacci.add(next);
    }

    return fibonacci;
}

