public int maxUniqueSplit(String s) {
    // Base case: if the string is empty, return 0
    if (s.isEmpty()) {
        return 0;
    }

    // Use a set to keep track of unique substrings
    Set<String> uniqueSubstrings = new HashSet<>();

    // Iterate through the string to split it into substrings
    for (int i = 0; i < s.length(); i++) {
        // Start with the substring from the current character
        for (int j = i + 1; j <= s.length(); j++) {
            String currentSubstring = s.substring(i, j);
            // If the substring is not already in the set, add it
            if (!uniqueSubstrings.contains(currentSubstring)) {
                uniqueSubstrings.add(currentSubstring);
            }
            // If adding the current substring didn't increase the number of unique substrings, break the loop
            else {
                break;
            }
        }
    }

    // Return the number of unique substrings
    return uniqueSubstrings.size();
}

