public static int singleNumber(int[] nums) {
    // Initialize an integer to keep track of the count of each number
    int numCount = 0;

    // iterate through each element in the nums array
    for (int i = 0; i < nums.length; i++) {
        int count = 0;
        // Use a nested loop to count the occurrences of each number
        for (int j = 0; j < nums.length; j++) {
            if (nums[i] == nums[j]) {
                count++;
            }
        }
        // If the number appears only once, increment the count
        if (count == 1) {
            numCount++;
        }
    }

    // Iterate through the nums array again to find the single number
    for (int i = 0; i < nums.length; i++) {
        if (nums[numCount - 1] == nums[i]) {
            return nums[numCount - 1];
        }
    }

    // If no single number is found, return -1 (should not happen in the given problem)
    return -1;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> steppingNumbers = new ArrayList<>();
        if (low > high) {
            // Swap low and high if they are in the wrong order
            int temp = low;
            low = high;
            high = temp;
        }
        // Check if low is a stepping number
        if (isSteppingNumber(low)) {
            steppingNumbers.add(low);
        }
        // Check stepping numbers of length 2
        for (int i = 1; i <= 9; i++) {
            if (isSteppingNumber(i)) {
                steppingNumbers.add(i);
            }
        }
        // Check stepping numbers of length 3 to high
        for (int i = 10; i <= high; i++) {
            if (isSteppingNumber(i)) {
                steppingNumbers.add(i);
            }
        }
        return steppingNumbers;
    }

private static boolean isSteppingNumber(int number) {
        int lastDigit = -1;
        for (int digit : Integer.toString(number).toCharArray()) {
            if (lastDigit == -1 || Math.abs(lastDigit - digit) != 1) {
                return false;
            }
            lastDigit = digit - '0';
        }
        return true;
    }

