                    up[i + 1][j + 1] = 1 + up[i][j] + left[i][j];
                if (i - 1 >= 0 && j + 1 < cols && mat[i - 1][j + 1] == 1)
                    down[i - 1][j + 1] = 1 + down[i][j] + right[i][j];
            }
            max_len = Math.max(max_len, up[i][j] + left[i][j] + down[i][j] + right[i][j] + row_diag[i][j] + col_diag[i][j]);
        }
    }

    return max_len;
}

public static String addThousandSeparator(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be a non-negative integer");
    }

    StringBuilder result = new StringBuilder();
    int position = 0;
    while (n > 0) {
        if (position > 0) {
            result.insert(0, '.');
        }
        int digit = n % 10;
        result.insert(0, digit);
        n /= 10;
        position++;
    }

    return result.toString();
}

public static int squarePermutations(int[] A) {
        Set<int[]> perm = new HashSet<>();
        if (A.length < 2) {
            perm.add(new int[]{A[0]});
            return perm.size();
        }
        backtrack(0, A, new boolean[A.length], perm);
        return perm.size();
    }

private static void backtrack(int start, int[] A, boolean[] used, Set<int[]> perm) {
        if (start == A.length) {
            perm.add(new intA.Clone());
            return;
        }
        for (int i = start; i < A.length; i++) {
            if (used[i] || (i > start && !used[i - 1] && A[i] == A[i - 1])) {
                continue;
            }
            used[i] = true;
            backtrack(start + 1, A, used, perm);
            used[i] = false;
        }
    }

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int left[] = new int[n];
    int right[] = new int[n];
    int result = 0;

    // Find the left boundary of each bar
    left[0] = -1;
    for (int i = 1; i < n; i++) {
        while (i > 0 && heights[i] <= heights[i - 1]) {
            i = left[i - 1];
        }
        left[i] = (i > 0) ? i - 1 : -1;
    }

    // Find the right boundary of each bar
    right[n - 1] = n;
    for (int i = n - 2; i >= 0; i--) {
        while (i < n - 1 && heights[i] <= heights[i + 1]) {
            i = right[i + 1];
        }
        right[i] = (i < n - 1) ? i + 1 : n;
    }

    // Calculate the area of each bar and find the maximum area
    for (int i = 0; i < n; i++) {
        result = Math.max(result, heights[i] * (right[i] - left[i] - 1));
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        throw new IllegalArgumentException("Input matrix cannot be null or empty");
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int index = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            result[index++] = mat[i][j];
        }
        for (int j = 1; j < rows - i && j < cols; j++) {
            result[index++] = mat[i + j][j];
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    // Convert the integer to a string
    String str = String.valueOf(n);
    if (str.length() == 1) return -1; // Single-digit numbers can't be rearranged

    // Find the smallest possible digit to swap with the first digit
    for (int i = 0; i < str.length() - 1; i++) {
        char current = str.charAt(i);
        if (Character.digit(current, 10) > Character.digit(str.charAt(i + 1), 10)) {
            // Create a new string by swapping the first digit with the smallest one longer
            StringBuilder newStr = new StringBuilder(str.substring(i) + str.charAt(i) + str.substring(i + 1));
            try {
                // Convert the string back to an integer and check if it's greater than n
                int result = Integer.parseInt(newStr.toString());
                if (result > n) return result;
            } catch (NumberFormatException e) {
                // Handle case where the resulting number is not a valid integer
                // For example, this can happen if the constructed number is not a valid number (like '111')
            }
        }
    }
    return -1; // No valid smaller number found
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        throw new IllegalArgumentException("N must be a positive integer.");
    }

    for (int i = (int) Math.pow(10, (n - 1)) / 10; i < Math.pow(10, n) / 10; i++) {
        String numStr = String.valueOf(i);
        long reversedNum = Long.parseLong(new StringBuilder(numStr).reverse().toString());

        if (reversedNum == i) {
            result.add(numStr);
        }
    }

    return result;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length < 3 || points[0].length != 2 || points[1].length != 2 || points[2].length != 2) {
        throw new IllegalArgumentException("Invalid input");
    }

    if (
        points[0][0] == points[1][0] && points[0][1] == points[1][1]
        || points[0][0] == points[2][0] && points[0][1] == points[2][1]
        || points[1][0] == points[2][0] && points[1][1] == points[2][1]
    ) {
        return false;
    }

    // Calculate the slopes of the sides
    double slope1 = calculateSlope(points[0], points[1]);
    double slope2 = calculateSlope(points[1], points[2]);

    // Check if the slopes are not equal, forming a triangle
    return slope1 != slope2;
}

private double calculateSlope(int[] point1, int[] point2) {
    return (point2[1] - point1[1]) / (point2[0] - point1[0]);
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    int i = 0; // index for 2
    int j = 0; // index for 3
    int k = 0; // index for 5

    for (int i = 1; i < n; i++) {
        int min = Math.min(uglyNumbers[i - 1] * 2, Math.min(uglyNumbers[i - 1] * 3, uglyNumbers[i - 1] * 5));
        uglyNumbers[i] = min;

        if (min == uglyNumbers[i - 1] * 2) {
            i++;
            j++;
        }
        if (min == uglyNumbers[i - 1] * 3) {
            i++;
            k++;
        }
        if (min == uglyNumbers[i - 1] * 5) {
            i++;
        }
    }

    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        throw new IllegalArgumentException("Input string cannot be null or empty");
    }

    int maxEnergy = 0;
    int currentEnergy = 1;
    char previousChar = s.charAt(0);

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == previousChar) {
            currentEnergy++;
        } else {
            previousChar = s.charAt(i);
            maxEnergy = Math.max(maxEnergy, currentEnergy);
            currentEnergy = 1;
        }
    }

    maxEnergy = Math.max(maxEnergy, currentEnergy); // Handle the last group of characters

    return maxEnergy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        node(n, i, result);
    }
    Collections.sort(result);
    return result;
}

private static void node(int n, int val, List<Integer> result) {
    if (val > n) return;
    result.add(val);
    for (int i = 0; i <= 9; i++) {
        node(n, 10 * val + i, result);
    }
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Array cannot be null or empty");
    }

    HashSet<Integer> uniqueElements = new HashSet<>();
    for (int num : nums) {
        uniqueElements.add(num);
    }

    return uniqueElements.stream().mapToInt(Integer::intValue).sum();
}

public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);

    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }

    StringBuilder result = new StringBuilder();
    int start = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == ' ') {
            // Reverse the current word
            reverse(result, start, i - 1);
            result.append(' ');
            start = i + 1;
        }
    }

    // Reverse the last word
    reverse(result, start, s.length() - 1);
    return result.toString();
}

private void reverse(StringBuilder sb, int start, int end) {
    while (start < end) {
        char temp = sb.charAt(start);
        sb.setCharAt(start, sb.charAt(end));
        sb.setCharAt(end, temp);
        start++;
        end--;
    }
}
